import ru.mebel3d.app.core.*

fun main() {
    var checks = 0
    fun check(ok: Boolean, message: String) { check(ok) { message }; checks++ }
    val room = RoomModel(id = "r1", widthMm = 5000, depthMm = 4000, heightMm = 2700)
    val base = ProjectModel("p1", "Тест", listOf(room), activeRoomId = "r1")
    check(ProjectValidator.validate(base).isEmpty(), "valid empty project")
    val calibrated = GeometryEngine.calibratePhoto(RoomPhotoReference("ph1", "content://photo"), 1000, 500)
    val withPhoto = base.copy(rooms = listOf(room.copy(photos = listOf(calibrated))))
    check(ProjectValidator.validate(withPhoto).isEmpty(), "calibrated photo")
    check(ProjectValidator.validate(base.copy(activeRoomId = "missing")).isNotEmpty(), "missing active room")
    check(ProjectValidator.validate(base.copy(rooms = listOf(room, room.copy(name = "Duplicate")))).isNotEmpty(), "duplicate room id")
    check(ProjectValidator.validate(base.copy(rooms = listOf(room.copy(photos = listOf(RoomPhotoReference("bad", "")))))).isNotEmpty(), "blank photo uri")
    check(ProjectValidator.validate(base.copy(rooms = listOf(room.copy(photos = listOf(RoomPhotoReference("partial", "content://x", knownLengthMm = 1000)))))).isNotEmpty(), "partial calibration")
    val badPhotoSize = RoomPhotoReference("bad-size", "content://x", imageWidthPx = 1200)
    check(ProjectValidator.validate(base.copy(rooms = listOf(room.copy(photos = listOf(badPhotoSize))))).isNotEmpty(), "partial image dimensions")
    val badAnnotation = PhotoAnnotation("mark", PhotoAnnotationKind.WINDOW, 1100, 10, 200, 100)
    val boundedPhoto = RoomPhotoReference("bounded", "content://x", imageWidthPx = 1200, imageHeightPx = 900, annotations = listOf(badAnnotation))
    check(ProjectValidator.validate(base.copy(rooms = listOf(room.copy(photos = listOf(boundedPhoto))))).any { it.objectId == "mark" }, "annotation outside image bounds")
    val duplicateMarks = boundedPhoto.copy(annotations = listOf(badAnnotation.copy(xPx = 10, widthPx = 100), badAnnotation.copy(xPx = 200, widthPx = 100)))
    check(ProjectValidator.validate(base.copy(rooms = listOf(room.copy(photos = listOf(duplicateMarks))))).any { it.objectId == "bounded" }, "duplicate annotation IDs")
    val unnamedEngineering = room.copy(engineering = listOf(EngineeringElement("e1", " ", EngineeringKind.OUTLET, Vec3Mm(100, 100, 300))))
    check(ProjectValidator.validate(base.copy(rooms = listOf(unnamedEngineering))).any { it.objectId == "e1" }, "engineering marker requires a name")
    val furniture = FurnitureItem("f1", "Стол", Size3Mm(1000, 600, 750), Vec3Mm(1500, 1500), roomId = "r1")
    check(ProjectValidator.validate(base.copy(furniture = listOf(furniture))).isEmpty(), "valid furniture")
    check(ProjectValidator.validate(base.copy(furniture = listOf(furniture, furniture.copy(name = "Копия")))).isNotEmpty(), "duplicate furniture id")
    check(ProjectValidator.validate(base.copy(furniture = listOf(furniture.copy(roomId = "missing")))).isNotEmpty(), "orphan furniture")
    val overlap = furniture.copy(id = "f2", position = Vec3Mm(1700, 1500))
    check(ProjectValidator.validate(base.copy(furniture = listOf(furniture, overlap))).any { it.code == GeometryIssueCode.COLLISION }, "furniture collision")
    val assembly = FurnitureAssembly("a1", "Полка", Vec3Mm(0,0), listOf(FurniturePart("part", "Панель", Size3Mm(800, 300, 18), Vec3Mm(0,0))))
    check(ProjectValidator.validate(base.copy(assemblies = listOf(assembly))).isEmpty(), "valid assembly")
    check(ProjectValidator.validate(base.copy(assemblies = listOf(assembly, assembly))).isNotEmpty(), "duplicate assembly id")
    val side = FurniturePart("side", "Боковина", Size3Mm(18, 500, 700), Vec3Mm(0, 0, 0))
    val shelf = FurniturePart("shelf", "Полка", Size3Mm(564, 500, 18), Vec3Mm(18, 0, 100))
    val validJoint = AssemblyJoint("j1", JointKind.CONFIRMAT, "side", "shelf", 7, 50, 20, 18)
    val connectedAssembly = FurnitureAssembly("a2", "Корпус", Vec3Mm(0, 0), listOf(side, shelf), listOf(validJoint))
    check(ProjectValidator.validate(base.copy(assemblies = listOf(connectedAssembly))).isEmpty(), "valid joint is accepted")
    val danglingJoint = validJoint.copy(secondPartId = "missing")
    check(ProjectValidator.validate(base.copy(assemblies = listOf(connectedAssembly.copy(joints = listOf(danglingJoint)))))
        .any { it.code == GeometryIssueCode.INVALID_ASSEMBLY }, "project rejects joint references to missing parts")
    val selfJoint = validJoint.copy(secondPartId = "side")
    check(ProjectValidator.validate(base.copy(assemblies = listOf(connectedAssembly.copy(joints = listOf(selfJoint)))))
        .any { it.code == GeometryIssueCode.INVALID_ASSEMBLY }, "project rejects self-joining joint")
    val duplicateJoint = connectedAssembly.copy(joints = listOf(validJoint, validJoint.copy(firstPartId = "shelf")))
    check(ProjectValidator.validate(base.copy(assemblies = listOf(duplicateJoint)))
        .any { it.code == GeometryIssueCode.INVALID_ASSEMBLY }, "project rejects duplicate joint IDs")
    val badDimensions = connectedAssembly.copy(joints = listOf(validJoint.copy(fastenerDiameterMm = -1)))
    check(ProjectValidator.validate(base.copy(assemblies = listOf(badDimensions)))
        .any { it.code == GeometryIssueCode.INVALID_ASSEMBLY }, "project rejects invalid joint dimensions")
    val warningOnlyJoint = connectedAssembly.copy(joints = listOf(validJoint.copy(edgeDistanceMm = 1)))
    check(ProjectValidator.validate(base.copy(assemblies = listOf(warningOnlyJoint))).isEmpty(), "manufacturing warnings do not block saving")
    val session = ProjectSession(base)
    val rejected = runCatching { session.edit { it.copy(activeRoomId = "missing") } }.isFailure
    check(rejected && !session.isDirty && !session.canUndo, "invalid edit is atomic")
    check(runCatching { ProjectValidator.requireValid(base.copy(name = "")) }.isFailure, "blank project name")
    println("ProjectValidatorSmoke: $checks checks passed")
}
